package vn.suncare.infrastructure.db;

import jakarta.persistence.Column;
import jakarta.persistence.MappedSuperclass;
import jakarta.persistence.PrePersist;
import jakarta.persistence.PreUpdate;
import java.time.Instant;

/**
 * Base auditing contract for mutable SQL Server tables (DB-06):
 * - created_at and updated_at are stored in UTC (datetime2(3)).
 * - updated_at is explicitly refreshed on every UPDATE since SQL Server DEFAULT only applies on INSERT.
 * - version maps to SQL Server rowversion (read-only from Java, generated by SQL Server).
 */
@MappedSuperclass
public abstract class MutableEntityAuditSupport {

	@Column(name = "created_at", nullable = false, updatable = false)
	private Instant createdAt;

	@Column(name = "updated_at", nullable = false)
	private Instant updatedAt;

	@Column(name = "version", insertable = false, updatable = false)
	private byte[] version;

	@PrePersist
	protected void onCreate() {
		Instant now = Instant.now();
		if (this.createdAt == null) {
			this.createdAt = now;
		}
		this.updatedAt = now;
	}

	@PreUpdate
	protected void onUpdate() {
		this.updatedAt = Instant.now();
	}

	public void touchUpdatedAt(Instant nowUtc) {
		this.updatedAt = nowUtc != null ? nowUtc : Instant.now();
		if (this.createdAt == null) {
			this.createdAt = this.updatedAt;
		}
	}

	public Instant getCreatedAt() {
		return createdAt;
	}

	public Instant getUpdatedAt() {
		return updatedAt;
	}

	public byte[] getVersion() {
		return version == null ? null : version.clone();
	}
}

